CREATE TABLE IF NOT EXISTS PBS_BROADCAST_PROGRAM (contents_id TEXT not null, seq_no TEXT not null, real_epsd_no TEXT, pgm_gr_id TEXT, connector_id TEXT, ser_id TEXT, ser_no TEXT, season_id TEXT, season_no TEXT, summary TEXT, pgm_img_url_name TEXT, gen_img_url_name TEXT, org_genre_type TEXT, org_genre_code TEXT, com_genre_type TEXT, com_genre_code TEXT, sub_genre_type TEXT, sub_genre_code TEXT, make_com TEXT, make_cntry TEXT, make_year TEXT, aud_lang TEXT, data_lang TEXT, aud_qlty TEXT, usr_pplr_st TEXT, pplr_st TEXT, crt_date TEXT, pgmImgSize TEXT, genreImgSize TEXT, programLock TEXT, lgGenreCode2 TEXT, lgGenreName2 TEXT, castingFlag TEXT, item_id TEXT, use_flag TEXT, last_chg_date TEXT, last_chg_usr_no NUMERIC, gen_usr_no NUMERIC, PRIMARY KEY (contents_id, seq_no));
CREATE TABLE IF NOT EXISTS PBS_BROADCAST_SCHEDULE (schd_id TEXT not null, contents_id TEXT, seq_no TEXT, chan_code TEXT, start_time TEXT, end_time TEXT, schd_summary TEXT, time_type TEXT, schd_pgm_ttl TEXT, schd_sub_ttl TEXT, rebrdcst_flag TEXT, cap_flag TEXT, live_flag TEXT, data_brdcst_flag TEXT, sc_expln_brdcst_flag TEXT, sc_quality_gbn TEXT, sign_brdcst_flag TEXT, voice_multi_brdcst_count TEXT, three_d_flag TEXT, schd_adult_class_code TEXT, schd_age_grd_code TEXT, startTimeLong NUMERIC, endTimeLong NUMERIC, crt_date TEXT, use_flag TEXT not null, last_chg_date TEXT, last_chg_usr_no NUMERIC, gen_usr_no NUMERIC, PRIMARY KEY (schd_id, use_flag));
CREATE INDEX IF NOT EXISTS IDX_PBS_BROADCAST_PROGRAM ON PBS_BROADCAST_PROGRAM (contents_id ASC,seq_no ASC);
CREATE INDEX IF NOT EXISTS IDX_PBS_BROADCAST_SCHEDULE ON PBS_BROADCAST_SCHEDULE (schd_id ASC,use_flag ASC);
